class Solution {
    public int minStoneSum(int[] piles, int k) {
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        int sum = 0;
        for (int p : piles) {
            pq.offer(p);
            sum += p;
        }
        while (k-- > 0) {
            int x = pq.poll();
            int remove = x / 2;
            sum -= remove;
            pq.offer(x - remove);
        }
        return sum;
    }
}

