class Solution {
public:
    vector<int> topKFrequent(vector<int>& nums, int k) {
        unordered_map<int, int> cnt;
        for (int x : nums) cnt[x]++;
        vector<int> uniq;
        uniq.reserve(cnt.size());
        for (auto& [x, _] : cnt) uniq.push_back(x);
        int n = (int)uniq.size();
        int l = 0, r = n - 1, idx = n - k;
        while (l < r) {
            int pvt = l + rand() % (r - l + 1);
            swap(uniq[pvt], uniq[r]);
            int pivot = cnt[uniq[r]], store = l;
            for (int i = l; i < r; i++) {
                if (cnt[uniq[i]] < pivot) {
                    swap(uniq[store], uniq[i]);
                    store++;
                }
            }
            swap(uniq[store], uniq[r]);
            if (store == idx) break;
            if (store < idx) l = store + 1;
            else r = store - 1;
        }
        return vector<int>(uniq.begin() + idx, uniq.end());
    }
};

