            for (int i = l; i < r; i++) {
                if (cnt.get(uniq[i]) < pivot) {
                    swap(uniq, store, i);
                    store++;
                }
            }
            swap(uniq, store, r);
            if (store == idx) break;
            if (store < idx) l = store + 1;
            else r = store - 1;
        }
        return Arrays.copyOfRange(uniq, idx, n);
    }
    private void swap(int[] a, int i, int j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
    }
